Q: Toast Error message is shown multiple times - How to avoid it? A: <p>Currently <code>{error &amp;&amp; openNotification(error)}</code> runs on every render while the error persists.</p>
<p>You could place the notification logic in a <code>useEffect</code> like so:</p>
<pre><code>import { useEffect } from 'react';
export const App = () =&gt; {
    const { data, error } = useApiQuery();

    useEffect(() =&gt; {
        if (error) {
            openNotification(error);
        }
    }, [error]); // Only runs when error changes

    return (
        &lt;&gt;
            {/* Your components */}
        &lt;/&gt;
    );
}
</code></pre>
